SELECT id, session_id, event_type, page, RANK() OVER (PARTITION BY event_type ORDER BY duration_sec) duration_sec_rank, DENSE_RANK() OVER (PARTITION BY page ORDER BY duration_sec NULLS FIRST) duration_sec_dense_rank, LAG(duration_sec, 1) OVER (PARTITION BY event_type ORDER BY event_time, id) prev_duration_sec, SUM(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_duration_sec, MAX(duration_sec) OVER w_grp duration_sec_max_30d FROM web_events WINDOW w_grp AS (PARTITION BY page, session_id ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW);
